const lockLeaseForBilling = `-- name: LockLeaseForBilling :one
SELECT l.id, l.tenant_id, l.unit_id, u.property_id, l.start_date, l.entered_on, l.billed_from,
       l.term_months, l.planned_end_date, l.end_date, l.status, l.collector_staff_user_id
FROM lease l
JOIN unit u ON u.organization_id = l.organization_id AND u.id = l.unit_id
WHERE l.organization_id = $1 AND l.id = $2
FOR NO KEY UPDATE OF l
`

type LockLeaseForBillingParams struct {
	OrganizationID uuid.UUID
	ID             uuid.UUID
}

type LockLeaseForBillingRow struct {
	ID                   uuid.UUID
	TenantID             uuid.UUID
	UnitID               uuid.UUID
	PropertyID           uuid.UUID
	StartDate            time.Time
	EnteredOn            time.Time
	BilledFrom           time.Time
	TermMonths           int16
	PlannedEndDate       *time.Time
	EndDate              *time.Time
	Status               string
	CollectorStaffUserID uuid.NullUUID
}

// Locks one lease for generation and returns what generation needs. FOR NO KEY UPDATE OF the
// lease only, the same lock the lease service takes (LockLease), so generation and a change of
// the lease's dates run one after the other and each sees the other's committed rows. It does not
// conflict with the FOR KEY SHARE that inserting an invoice takes on the lease.
func (q *Queries) LockLeaseForBilling(ctx context.Context, arg LockLeaseForBillingParams) (LockLeaseForBillingRow, error) {
	row := q.db.QueryRow(ctx, lockLeaseForBilling, arg.OrganizationID, arg.ID)
	var i LockLeaseForBillingRow
	err := row.Scan(
		&i.ID,
		&i.TenantID,
		&i.UnitID,
		&i.PropertyID,
		&i.StartDate,
		&i.EnteredOn,
		&i.BilledFrom,
		&i.TermMonths,
		&i.PlannedEndDate,
		&i.EndDate,
		&i.Status,
		&i.CollectorStaffUserID,
	)
	return i, err
}

const lockTenantForAllocation = `-- name: LockTenantForAllocation :one
SELECT id FROM tenant
WHERE organization_id = $1 AND id = $2
FOR NO KEY UPDATE
`

type LockTenantForAllocationParams struct {
	OrganizationID uuid.UUID
	TenantID       uuid.UUID
}

// Serializes allocation per tenant. FOR NO KEY UPDATE, not FOR UPDATE: inserting a payment or
// an invoice takes FOR KEY SHARE on the tenant through its foreign key, which FOR UPDATE would
// wait on, so two transactions that each inserted a payment and then locked would deadlock.
func (q *Queries) LockTenantForAllocation(ctx context.Context, arg LockTenantForAllocationParams) (uuid.UUID, error) {
	row := q.db.QueryRow(ctx, lockTenantForAllocation, arg.OrganizationID, arg.TenantID)
	var id uuid.UUID
	err := row.Scan(&id)
	return id, err
}

